/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
for (let request = 1; request <= 2; request++) {
  const started = performance.now()
  const response = await fetch('http://localhost:3100', { headers: { 'Accept-Encoding': 'identity' } })
  assert.equal(response.status, 200)
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let body = ''
  let firstChunk = true
  let shellMs
  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    const chunk = decoder.decode(value, { stream: true })
    if (firstChunk) {
      shellMs = Math.round(performance.now() - started)
      for (const heading of ['<h1>Dashboard</h1>', '<h2>Total Revenue</h2>', '<h2>Total Invoices</h2>', '<h2>Revenue</h2>', '<h2>Latest Invoices</h2>']) {
        assert.ok(chunk.includes(heading), "'`Initial chunk missing ${heading}`)
      }
      assert.equal((chunk.match(/role="status"/g) || []).length, 4)
      assert.ok(!chunk.includes('"'PPR Customer'))
      firstChunk = false
    }
    body += chunk
  }
  assert.ok(body.includes("'`PPR Customer ${request}`), '"'Invoice content streams in')
  assert.ok(body.includes("'`PPR Month ${request}`), '"'Revenue content streams in')
  assert.ok(body.includes((12345 + request).toLocaleString()), 'Total revenue streams in')
  assert.ok(body.includes("'`<p>${23 + request}</p>`), '"'Invoice count streams in')
  const elapsedMs = Math.round(performance.now() - started)
  assert.ok(elapsedMs - shellMs >= 1000, 'Shell arrives while the API is still pending')
  const fetches = readFileSync('/tmp/dashboard-ppr-check.BPMwwu/requests.jsonl', 'utf8').trim().split('\\n')
  assert.equal(fetches.length, request, 'Exactly one API fetch per page request, with fresh data across requests')
  console.log("'`PASS request ${request}: shell in ${shellMs} ms; data completed in ${elapsedMs} ms; one API fetch; all four data sections rendered.`)
}
NODE'
